import React, { useState, useRef, useEffect } from 'react';
import { Card, CardHeader, Btn, Spinner } from '../components/ui/Card';
import api from '../utils/api';

// ── Helpers ──────────────────────────────────────────────────
const SYSTEM_PROMPT = `Tu es ARIA (Artificial Religious Intelligence Assistant), l'assistant IA intégré du système de gestion de LHM Madagascar (Lutheran Hour Ministries - Feon'ny Filazantsara).

Tu as accès aux données du système et tu aides l'équipe à :
- Analyser les performances des étudiants BCC (Bible Correspondence Course)
- Prédire les risques d'abandon ou d'échec
- Recommander des actions pour améliorer les résultats
- Analyser la gestion du personnel et des absences
- Suggérer des optimisations pour la gestion du stock
- Donner des insights sur les projets

Tu réponds en français, de manière professionnelle, concise et utile. Tu utilises des émojis pour rendre les réponses plus lisibles. Quand on te demande des prédictions, tu bases tes analyses sur les tendances observées dans les données.

Données actuelles du système disponibles dans le contexte de la conversation.`;

const SUGGESTIONS = [
  { icon:'📊', text:'Analyser les performances BCC', prompt:'Analyse les performances générales des étudiants BCC et identifie les tendances importantes.' },
  { icon:'🔮', text:'Prédire les risques d\'abandon', prompt:'Quels étudiants BCC sont à risque d\'abandon ou d\'échec ? Base-toi sur les données disponibles.' },
  { icon:'📦', text:'Optimiser le stock', prompt:'Analyse l\'état actuel du stock et donne des recommandations pour éviter les ruptures critiques.' },
  { icon:'👥', text:'Analyse du personnel', prompt:'Donne un aperçu de la gestion du personnel : absences, contrats, points d\'attention.' },
  { icon:'🎯', text:'Évaluer les projets', prompt:'Évalue l\'avancement des projets et identifie les risques potentiels de retard.' },
  { icon:'📅', text:'Prédire les pics d\'absence', prompt:'Sur la base des tendances, quelles périodes présentent des risques de congés élevés ?' },
];

function TypingIndicator() {
  return (
    <div style={{ display:'flex', gap:5, alignItems:'center', padding:'12px 16px' }}>
      {[0,1,2].map(i=>(
        <div key={i} style={{
          width:8, height:8, borderRadius:'50%', background:'#c9a84c',
          animation:'bounce 1.2s ease infinite',
          animationDelay:`${i*0.2}s`,
        }}/>
      ))}
      <style>{`@keyframes bounce{0%,80%,100%{transform:scale(0)}40%{transform:scale(1)}}`}</style>
    </div>
  );
}

function Message({ msg }) {
  const isUser = msg.role === 'user';
  return (
    <div style={{ display:'flex', justifyContent: isUser ? 'flex-end' : 'flex-start', marginBottom:16 }}>
      {!isUser && (
        <div style={{
          width:36, height:36, borderRadius:'50%', flexShrink:0, marginRight:10,
          background:'linear-gradient(135deg,#0f2044,#c9a84c)',
          display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1rem',
        }}>🤖</div>
      )}
      <div style={{
        maxWidth:'75%', padding:'12px 16px', borderRadius: isUser ? '18px 18px 4px 18px' : '18px 18px 18px 4px',
        background: isUser ? 'linear-gradient(135deg,#0f2044,#1a3a6e)' : 'white',
        color: isUser ? 'white' : '#0f2044',
        boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
        border: isUser ? 'none' : '1px solid #e5e7eb',
        fontSize:'0.88rem', lineHeight:1.6,
        whiteSpace:'pre-wrap',
      }}>
        {msg.content}
        <div style={{ fontSize:'0.68rem', opacity:.6, marginTop:6, textAlign: isUser?'right':'left' }}>
          {new Date(msg.time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}
        </div>
      </div>
      {isUser && (
        <div style={{
          width:36, height:36, borderRadius:'50%', flexShrink:0, marginLeft:10,
          background:'linear-gradient(135deg,#0f2044,#1a3a6e)',
          display:'flex', alignItems:'center', justifyContent:'center', fontSize:'0.75rem',
          color:'white', fontWeight:700,
        }}>Moi</div>
      )}
    </div>
  );
}

// ── Panneau de prédictions ───────────────────────────────────
function PredictionsPanel({ dashData, bccData }) {
  const [loading, setLoading] = useState(false);
  const [preds,   setPreds]   = useState(null);
  const [error,   setError]   = useState('');

  const runPredictions = async () => {
    setLoading(true); setError('');
    try {
      const context = buildContext(dashData, bccData);
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method:'POST',
        headers:{ 'Content-Type':'application/json' },
        body: JSON.stringify({
          model:'claude-sonnet-4-20250514', max_tokens:1000,
          system:`${SYSTEM_PROMPT}\n\nContexte actuel du système:\n${context}`,
          messages:[{ role:'user', content:`Génère une analyse prédictive structurée du système LHM Madagascar. 
Réponds UNIQUEMENT en JSON valide avec ce format exact:
{
  "resume": "Un résumé en 1-2 phrases de l'état général",
  "alertes": [{"niveau":"high|medium|low","titre":"...","description":"...","action":"..."}],
  "predictions": [{"domaine":"BCC|Stock|Personnel|Projets","titre":"...","probabilite":0-100,"impact":"positif|negatif|neutre","detail":"..."}],
  "recommandations": [{"priorite":1-3,"titre":"...","description":"...","benefice":"..."}]
}` }],
        }),
      });
      const data = await response.json();
      const text = data.content?.map(b => b.type==='text' ? b.text : '').join('').trim();
      const clean = text.replace(/```json|```/g,'').trim();
      setPreds(JSON.parse(clean));
    } catch(e) {
      setError('Impossible de générer les prédictions. Vérifiez votre connexion.');
    } finally { setLoading(false); }
  };

  const niveauColor = { high:'#dc2626', medium:'#f59e0b', low:'#16a34a' };
  const niveauBg    = { high:'#fee2e2', medium:'#fef9c3', low:'#dcfce7' };
  const niveauLabel = { high:'🔴 Critique', medium:'🟡 Attention', low:'🟢 Information' };

  if (!preds && !loading && !error) return (
    <div style={{ textAlign:'center', padding:'32px 16px' }}>
      <div style={{ fontSize:'3rem', marginBottom:14 }}>🔮</div>
      <h3 style={{ color:'#0f2044', marginBottom:8, fontFamily:"'Playfair Display',serif" }}>Analyse prédictive IA</h3>
      <p style={{ color:'#9ca3af', fontSize:'0.88rem', marginBottom:20, maxWidth:360, margin:'0 auto 20px' }}>
        L'IA analyse vos données en temps réel pour détecter les risques, tendances et opportunités.
      </p>
      <Btn variant="gold" onClick={runPredictions}>🔮 Lancer l'analyse IA</Btn>
    </div>
  );

  if (loading) return (
    <div style={{ textAlign:'center', padding:'40px 16px' }}>
      <div style={{ width:48, height:48, border:'3px solid #e5e7eb', borderTop:'3px solid #c9a84c',
        borderRadius:'50%', animation:'spin 0.8s linear infinite', margin:'0 auto 16px' }} />
      <p style={{ color:'#9ca3af', fontSize:'0.88rem' }}>Analyse en cours...</p>
    </div>
  );

  if (error) return (
    <div style={{ background:'#fee2e2', border:'1px solid #fca5a5', borderRadius:10, padding:'16px 20px', color:'#991b1b' }}>
      <p>⚠️ {error}</p>
      <button onClick={runPredictions} style={{ marginTop:10, background:'white', border:'1px solid #fca5a5', borderRadius:6, padding:'6px 14px', cursor:'pointer', color:'#dc2626', fontSize:'0.82rem', fontWeight:600 }}>Réessayer</button>
    </div>
  );

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
      {/* Résumé */}
      <div style={{ background:'linear-gradient(135deg,#0f2044,#1a3a6e)', borderRadius:12, padding:'16px 20px', color:'white' }}>
        <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:8 }}>
          <span style={{ fontSize:'1.2rem' }}>🤖</span>
          <p style={{ fontWeight:700, fontSize:'0.88rem', opacity:.8 }}>ARIA — Résumé exécutif</p>
        </div>
        <p style={{ fontSize:'0.9rem', lineHeight:1.6 }}>{preds.resume}</p>
      </div>

      {/* Alertes */}
      {preds.alertes?.length > 0 && (
        <div>
          <h4 style={{ fontSize:'0.8rem', fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:8 }}>⚠️ Alertes détectées</h4>
          {preds.alertes.map((a,i) => (
            <div key={i} style={{ background:niveauBg[a.niveau]||'#f3f4f6', border:`1px solid ${niveauColor[a.niveau]||'#e5e7eb'}30`,
              borderLeft:`4px solid ${niveauColor[a.niveau]||'#9ca3af'}`, borderRadius:10, padding:'10px 14px', marginBottom:8 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:4, flexWrap:'wrap', gap:4 }}>
                <p style={{ fontWeight:700, color:niveauColor[a.niveau], fontSize:'0.85rem' }}>{a.titre}</p>
                <span style={{ fontSize:'0.7rem', fontWeight:600, color:niveauColor[a.niveau] }}>{niveauLabel[a.niveau]||a.niveau}</span>
              </div>
              <p style={{ fontSize:'0.8rem', color:'#4b5563', marginBottom:4 }}>{a.description}</p>
              <p style={{ fontSize:'0.75rem', color:niveauColor[a.niveau], fontWeight:600 }}>→ {a.action}</p>
            </div>
          ))}
        </div>
      )}

      {/* Prédictions */}
      {preds.predictions?.length > 0 && (
        <div>
          <h4 style={{ fontSize:'0.8rem', fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:8 }}>🔮 Prédictions</h4>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(220px,1fr))', gap:10 }}>
            {preds.predictions.map((p,i) => {
              const impactColor = p.impact==='positif'?'#16a34a':p.impact==='negatif'?'#dc2626':'#6b7280';
              const probColor   = p.probabilite>=70?'#dc2626':p.probabilite>=40?'#f59e0b':'#16a34a';
              return (
                <div key={i} style={{ border:'1px solid #e5e7eb', borderRadius:12, padding:'12px 14px', background:'white' }}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8 }}>
                    <span style={{ background:'#f0f4ff', color:'#0f2044', padding:'2px 8px', borderRadius:6, fontSize:'0.7rem', fontWeight:600 }}>{p.domaine}</span>
                    <span style={{ fontWeight:700, color:probColor, fontSize:'0.82rem' }}>{p.probabilite}%</span>
                  </div>
                  <p style={{ fontWeight:600, fontSize:'0.85rem', color:'#0f2044', marginBottom:5 }}>{p.titre}</p>
                  <p style={{ fontSize:'0.75rem', color:'#6b7280', marginBottom:6 }}>{p.detail}</p>
                  <div style={{ height:5, background:'#e5e7eb', borderRadius:99 }}>
                    <div style={{ height:'100%', width:`${p.probabilite}%`, background:probColor, borderRadius:99, transition:'width .6s' }}/>
                  </div>
                  <p style={{ fontSize:'0.7rem', color:impactColor, marginTop:5, fontWeight:600 }}>
                    {p.impact==='positif'?'↑ Impact positif':p.impact==='negatif'?'↓ Impact négatif':'→ Impact neutre'}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Recommandations */}
      {preds.recommandations?.length > 0 && (
        <div>
          <h4 style={{ fontSize:'0.8rem', fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:8 }}>💡 Recommandations prioritaires</h4>
          {preds.recommandations.sort((a,b)=>a.priorite-b.priorite).map((r,i) => (
            <div key={i} style={{ display:'flex', gap:12, padding:'10px 14px', border:'1px solid #e5e7eb', borderRadius:10, marginBottom:8, background:'white' }}>
              <div style={{ width:28, height:28, borderRadius:'50%', background:r.priorite===1?'#fee2e2':r.priorite===2?'#fef9c3':'#dcfce7',
                color:r.priorite===1?'#dc2626':r.priorite===2?'#d97706':'#16a34a',
                display:'flex', alignItems:'center', justifyContent:'center', fontWeight:700, fontSize:'0.8rem', flexShrink:0 }}>
                {r.priorite}
              </div>
              <div>
                <p style={{ fontWeight:600, fontSize:'0.85rem', color:'#0f2044', marginBottom:3 }}>{r.titre}</p>
                <p style={{ fontSize:'0.78rem', color:'#6b7280', marginBottom:4 }}>{r.description}</p>
                <p style={{ fontSize:'0.75rem', color:'#16a34a', fontWeight:600 }}>✅ {r.benefice}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      <button onClick={runPredictions}
        style={{ background:'transparent', border:'1px solid #e5e7eb', borderRadius:8, padding:'8px 16px',
          cursor:'pointer', fontSize:'0.78rem', color:'#9ca3af', fontWeight:600 }}>
        🔄 Actualiser l'analyse
      </button>
    </div>
  );
}

// ── Contexte système ─────────────────────────────────────────
function buildContext(dash, bcc) {
  const parts = [];
  if (dash?.stats) {
    const s = dash.stats;
    parts.push(`SYSTÈME LHM MADAGASCAR:
- Personnel actif: ${s.totalPersonnel}
- Volontaires: ${s.totalVolunteers}
- Projets actifs: ${s.activeProjects}
- Projets en retard: ${s.delayedProjects||0}
- Stock critique: ${s.criticalStock} articles
- Congés en attente: ${s.pendingLeave}
- Valeur stock total: ${s.totalStockValue?.toLocaleString('fr-FR')||0} Ar`);
  }
  if (bcc) {
    parts.push(`\nBCC (Bible Correspondence Course):
- Total étudiants: ${bcc.total}
- Français: ${bcc.parLangue?.Français||0}, English: ${bcc.parLangue?.English||0}, Malagasy: ${bcc.parLangue?.Malagasy||0}
- Actifs: ${bcc.parStatut?.actif||0}, Terminés: ${bcc.parStatut?.termine||0}, Inactifs: ${bcc.parStatut?.inactif||0}
- Mentions: Très Bien=${bcc.mentions?.['Très Bien']||0}, Bien=${bcc.mentions?.['Bien']||0}, Passable=${bcc.mentions?.['Passable']||0}, Insuffisant=${bcc.mentions?.['Insuffisant']||0}`);
  }
  return parts.join('\n') || 'Données non disponibles';
}

// ══════════════════════════════════════════════════════════════
// PAGE PRINCIPALE IA
// ══════════════════════════════════════════════════════════════
export default function AIPage() {
  const [messages,   setMessages]   = useState([
    { role:'assistant', content:`Bonjour ! Je suis **ARIA**, votre assistant IA pour LHM Madagascar. 🤖✝️\n\nJe peux vous aider à :\n• Analyser les performances des étudiants BCC\n• Prédire les risques (abandon, stock critique, surcharge)\n• Recommander des actions prioritaires\n• Répondre à vos questions sur les données du système\n\nQue puis-je faire pour vous aujourd'hui ?`, time: Date.now() },
  ]);
  const [input,      setInput]      = useState('');
  const [loading,    setLoading]    = useState(false);
  const [activeTab,  setActiveTab]  = useState('chat');
  const [dashData,   setDashData]   = useState(null);
  const [bccData,    setBccData]    = useState(null);
  const bottomRef = useRef();
  const inputRef  = useRef();

  useEffect(() => {
    document.getElementById('page-title') && (document.getElementById('page-title').textContent = 'ARIA — Intelligence Artificielle');
    // Charger les données pour le contexte IA
    Promise.all([
      api.get('/dashboard').catch(()=>null),
      api.get('/bcc/stats').catch(()=>null),
    ]).then(([d,b]) => {
      if (d) setDashData(d.data);
      if (b) setBccData(b.data.data);
    });
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior:'smooth' });
  }, [messages, loading]);

  const sendMessage = async (text = input) => {
    if (!text.trim() || loading) return;
    const userMsg = { role:'user', content:text.trim(), time: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput(''); setLoading(true);

    try {
      const context = buildContext(dashData, bccData);
      const history = messages.slice(-8).map(m => ({ role: m.role, content: m.content }));

      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method:'POST',
        headers:{ 'Content-Type':'application/json' },
        body: JSON.stringify({
          model:'claude-sonnet-4-20250514', max_tokens:1000,
          system:`${SYSTEM_PROMPT}\n\nContexte actuel:\n${context}`,
          messages:[...history, { role:'user', content: text.trim() }],
        }),
      });

      const data = await response.json();
      const reply = data.content?.map(b => b.type==='text' ? b.text : '').join('') || 'Désolé, je n\'ai pas pu répondre.';
      setMessages(prev => [...prev, { role:'assistant', content:reply, time:Date.now() }]);
    } catch(e) {
      setMessages(prev => [...prev, { role:'assistant', content:'⚠️ Erreur de connexion à l\'API. Vérifiez votre réseau.', time:Date.now() }]);
    } finally {
      setLoading(false);
      setTimeout(()=>inputRef.current?.focus(), 100);
    }
  };

  const handleKey = e => { if (e.key==='Enter'&&!e.shiftKey) { e.preventDefault(); sendMessage(); } };

  return (
    <div className="animate-fade">
      {/* Header */}
      <div style={{ background:'linear-gradient(135deg,#0f2044,#1a3a6e)', borderRadius:16, padding:'20px 28px',
        marginBottom:20, display:'flex', alignItems:'center', gap:16, flexWrap:'wrap',
        boxShadow:'0 8px 32px rgba(15,32,68,0.2)' }}>
        <div style={{ width:56, height:56, borderRadius:'50%', background:'linear-gradient(135deg,#c9a84c,#e0c06e)',
          display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.6rem', flexShrink:0,
          boxShadow:'0 4px 14px rgba(201,168,76,0.4)' }}>🤖</div>
        <div style={{ flex:1, color:'white' }}>
          <h2 style={{ fontFamily:"'Playfair Display',serif", fontSize:'1.3rem', fontWeight:700, marginBottom:3 }}>
            ARIA — Intelligence Artificielle
          </h2>
          <p style={{ opacity:.75, fontSize:'0.85rem' }}>
            Artificial Religious Intelligence Assistant · LHM Madagascar
          </p>
        </div>
        <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
          {['Analyse prédictive','Chat IA','Recommandations'].map(t=>(
            <span key={t} style={{ background:'rgba(201,168,76,0.2)', border:'1px solid rgba(201,168,76,0.3)',
              color:'#e0c06e', padding:'4px 12px', borderRadius:20, fontSize:'0.75rem', fontWeight:600 }}>
              {t}
            </span>
          ))}
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display:'flex', borderBottom:'2px solid #f3f4f6', marginBottom:16 }}>
        {[{id:'chat',label:'💬 Chat IA'},{id:'predictions',label:'🔮 Prédictions & Alertes'}].map(t=>(
          <button key={t.id} onClick={()=>setActiveTab(t.id)}
            style={{ padding:'10px 22px', border:'none', background:'transparent', cursor:'pointer',
              fontSize:'0.88rem', fontWeight:600,
              color:activeTab===t.id?'#0f2044':'#9ca3af',
              borderBottom:activeTab===t.id?'2px solid #c9a84c':'2px solid transparent',
              marginBottom:'-2px' }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ── CHAT ── */}
      {activeTab==='chat' && (
        <div style={{ display:'grid', gridTemplateColumns:'1fr 280px', gap:16, alignItems:'start' }}>
          <Card style={{ display:'flex', flexDirection:'column', height:'72vh' }}>
            {/* Messages */}
            <div style={{ flex:1, overflowY:'auto', padding:'16px 20px' }}>
              {messages.map((m,i) => <Message key={i} msg={m}/>)}
              {loading && (
                <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                  <div style={{ width:36, height:36, borderRadius:'50%', background:'linear-gradient(135deg,#0f2044,#c9a84c)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1rem' }}>🤖</div>
                  <div style={{ background:'white', border:'1px solid #e5e7eb', borderRadius:'18px 18px 18px 4px', overflow:'hidden' }}>
                    <TypingIndicator/>
                  </div>
                </div>
              )}
              <div ref={bottomRef}/>
            </div>

            {/* Input */}
            <div style={{ borderTop:'1px solid #f3f4f6', padding:'14px 20px', background:'#fafafa' }}>
              <div style={{ display:'flex', gap:10, alignItems:'flex-end' }}>
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={e=>setInput(e.target.value)}
                  onKeyDown={handleKey}
                  placeholder="Posez votre question à ARIA... (Entrée pour envoyer)"
                  rows={2} disabled={loading}
                  style={{ flex:1, resize:'none', padding:'10px 14px', border:'1.5px solid #e5e7eb',
                    borderRadius:12, fontSize:'0.88rem', outline:'none', fontFamily:'Inter,sans-serif',
                    background:'white' }}
                  onFocus={e=>e.target.style.borderColor='#c9a84c'}
                  onBlur={e=>e.target.style.borderColor='#e5e7eb'}
                />
                <button onClick={()=>sendMessage()} disabled={loading||!input.trim()}
                  style={{ width:44, height:44, borderRadius:'50%', border:'none',
                    background: input.trim()&&!loading ? 'linear-gradient(135deg,#0f2044,#1a3a6e)':'#e5e7eb',
                    color: input.trim()&&!loading ? 'white':'#9ca3af',
                    cursor: input.trim()&&!loading ? 'pointer':'not-allowed',
                    display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.1rem',
                    flexShrink:0, transition:'all 0.2s' }}>
                  ➤
                </button>
              </div>
              <p style={{ fontSize:'0.68rem', color:'#d1d5db', marginTop:6, textAlign:'right' }}>
                Shift+Entrée pour nouvelle ligne · Entrée pour envoyer
              </p>
            </div>
          </Card>

          {/* Suggestions */}
          <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
            <p style={{ fontSize:'0.75rem', fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:4 }}>
              💡 Suggestions rapides
            </p>
            {SUGGESTIONS.map((s,i) => (
              <button key={i} onClick={()=>sendMessage(s.prompt)}
                disabled={loading}
                style={{ background:'white', border:'1px solid #e5e7eb', borderRadius:10,
                  padding:'10px 14px', cursor:loading?'not-allowed':'pointer', textAlign:'left',
                  display:'flex', alignItems:'center', gap:10, transition:'all 0.15s',
                  opacity:loading?0.6:1 }}
                onMouseEnter={e=>{e.currentTarget.style.borderColor='#c9a84c';e.currentTarget.style.background='#fefce8'}}
                onMouseLeave={e=>{e.currentTarget.style.borderColor='#e5e7eb';e.currentTarget.style.background='white'}}>
                <span style={{ fontSize:'1.2rem' }}>{s.icon}</span>
                <span style={{ fontSize:'0.8rem', fontWeight:500, color:'#0f2044', lineHeight:1.3 }}>{s.text}</span>
              </button>
            ))}

            {messages.length > 2 && (
              <button onClick={()=>{ setMessages([messages[0]]); }}
                style={{ background:'transparent', border:'1px solid #fca5a5', borderRadius:8,
                  padding:'8px 12px', cursor:'pointer', fontSize:'0.75rem', color:'#dc2626', fontWeight:600, marginTop:4 }}>
                🗑️ Effacer la conversation
              </button>
            )}
          </div>
        </div>
      )}

      {/* ── PRÉDICTIONS ── */}
      {activeTab==='predictions' && (
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16 }}>
          <Card>
            <CardHeader title="Analyse prédictive IA" subtitle="ARIA analyse vos données en temps réel"/>
            <PredictionsPanel dashData={dashData} bccData={bccData}/>
          </Card>

          <div style={{ display:'flex', flexDirection:'column', gap:14 }}>
            {/* Contexte données disponibles */}
            <Card>
              <CardHeader title="Données analysées" subtitle="Sources utilisées par ARIA"/>
              <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
                {[
                  { icon:'👥', label:'Personnel', value:dashData?.stats?.totalPersonnel||0, unit:'actifs' },
                  { icon:'📖', label:'Étudiants BCC', value:bccData?.total||0, unit:'inscrits' },
                  { icon:'📦', label:'Stock critique', value:dashData?.stats?.criticalStock||0, unit:'articles', alert:dashData?.stats?.criticalStock>0 },
                  { icon:'📅', label:'Congés', value:dashData?.stats?.pendingLeave||0, unit:'en attente', alert:dashData?.stats?.pendingLeave>0 },
                  { icon:'🎯', label:'Projets actifs', value:dashData?.stats?.activeProjects||0, unit:'en cours' },
                  { icon:'⚠️', label:'Projets retardés', value:dashData?.stats?.delayedProjects||0, unit:'retards', alert:dashData?.stats?.delayedProjects>0 },
                ].map(item => (
                  <div key={item.label} style={{ display:'flex', alignItems:'center', gap:10,
                    padding:'8px 12px', borderRadius:9, background:item.alert?'#fef2f2':'#f8faff',
                    border:`1px solid ${item.alert?'#fca5a5':'#e5e7eb'}` }}>
                    <span style={{ fontSize:'1.1rem' }}>{item.icon}</span>
                    <span style={{ flex:1, fontSize:'0.82rem', color:'#4b5563', fontWeight:500 }}>{item.label}</span>
                    <span style={{ fontWeight:700, color:item.alert?'#dc2626':'#0f2044', fontSize:'1rem' }}>{item.value}</span>
                    <span style={{ fontSize:'0.7rem', color:'#9ca3af' }}>{item.unit}</span>
                  </div>
                ))}
              </div>
            </Card>

            {/* Capacités IA */}
            <Card>
              <CardHeader title="Capacités ARIA" subtitle="Ce que l'IA peut faire pour vous"/>
              <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
                {[
                  { icon:'🔮', title:'Prédiction abandons', desc:'Identifie les étudiants BCC à risque' },
                  { icon:'📦', title:'Optimisation stock', desc:'Anticipe les ruptures de stock' },
                  { icon:'👥', title:'Gestion RH', desc:'Analyse les tendances d\'absences' },
                  { icon:'💬', title:'Questions libres', desc:'Posez n\'importe quelle question sur vos données' },
                ].map(c => (
                  <div key={c.title} style={{ display:'flex', gap:10, padding:'8px 0', borderBottom:'1px solid #f3f4f6' }}>
                    <span style={{ fontSize:'1.1rem', flexShrink:0 }}>{c.icon}</span>
                    <div>
                      <p style={{ fontWeight:600, fontSize:'0.82rem', color:'#0f2044' }}>{c.title}</p>
                      <p style={{ fontSize:'0.75rem', color:'#9ca3af' }}>{c.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}
